import catalog from './skit-titles.json';

// English PC titles live in APPKEEP/TOS_TEXT.TXB, separate from the SKP scripts.
// IDs are the decimal selectors used by the restored test maps.
// Generated by scripts/prepare-skit-titles.py from canonical rows in
// tos-60-experiments/skit-id/skit-names-and-ids.json. That research export is
// produced by export_skit_names.py using the executable's filename/title tables.
const slots: Readonly<Record<string, { id: number; title: string }>> = catalog;

/** undefined means an unknown filename; '' means a known slot without an English title. */
export function skitTitle(filename: string): string | undefined {
  const key = filename.toUpperCase();
  return Object.hasOwn(slots, key) ? slots[key].title.trim() : undefined;
}

/** Canonical test-map selector ID, independent of the filename suffix or title index. */
export function skitId(filename: string): number | undefined {
  const key = filename.toUpperCase();
  return Object.hasOwn(slots, key) ? slots[key].id : undefined;
}
